# Реализуйте параметризованный декоратор @repeat(num_times)
from functools import wraps

def repeat(num_times=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(num_times):
                results.append(func(*args, **kwargs))
            return results[-1]
        return wrapper
    return decorator

