from concurrent.futures import (
    ProcessPoolExecutor,
    as_completed,
)

def risky_task(n):
    if n == 3:
        raise ValueError(f"Задача {n} упала намеренно")
    return n ** 2

if __name__ == '__main__':
    results = {}
    with ProcessPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(risky_task, i): i for i in range(5)}
        for future in as_completed(futures):
            n = futures[future]
            try:
                results[n] = future.result()
            except ValueError as e:
                results[n] = f"ошибка: {e}"

    print(results)
    # {0: 0, 1: 1, 2: 4, 3: 'ошибка: Задача 3
    # упала намеренно', 4: 16}
    # одна упавшая задача не роняет весь пул —
    # остальные результаты доступны

