# Постройте ленивый генераторный конвейер (pipeline) анализа логов за O(1) памяти
from itertools import islice

def parse_lines(raw_lines):
    for line in raw_lines:
        parts = line.strip().split("|")
        if len(parts) == 3:
            yield {"level": parts[0], "service": parts[1], "ms": int(parts[2])}

def filter_slow_errors(records, min_ms: int = 500):
    return (r for r in records if r["level"] == "ERROR" and r["ms"] >= min_ms)

